require __DIR__.'/_public-page.php';
loom_public_page('Forgot password','Request a secure, one-time password reset link for a permanent LOOM account.',
'<section class="card"><h2>Reset your password</h2><p>Enter the email address on your permanent LOOM account. For privacy, LOOM gives the same response whether or not an account exists.</p><form id="forgotForm" style="display:grid;gap:10px;max-width:520px"><input id="forgotEmail" type="email" autocomplete="email" required placeholder="you@example.com" style="padding:12px;border:1px solid #d5e3d8;border-radius:10px;font:inherit"><button type="submit" style="border:0;border-radius:10px;padding:12px 16px;background:#173f27;color:#fff;font-weight:900;cursor:pointer">Send reset link</button><div id="forgotMsg" style="min-height:22px;color:#52675a;font-size:13px;line-height:1.5"></div></form></section><script>document.addEventListener("DOMContentLoaded",()=>{const f=document.getElementById("forgotForm"),m=document.getElementById("forgotMsg");f?.addEventListener("submit",async e=>{e.preventDefault();m.textContent="Requesting reset link…";try{const r=await fetch("api/email.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"request-password-reset",email:document.getElementById("forgotEmail").value})});const j=await r.json();m.textContent=j.message||"If that account exists, a reset email will be sent.";}catch{m.textContent="The request could not be completed right now. Try again later.";}})})</script>','forgot-password.php',false,true);
